import math

def distance(a, b):
    return math.sqrt((a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2)

def nearest_center(p, centers):
    return min(range(len(centers)), key=lambda i: distance(p, centers[i]))
A, B, C = (50000, 2), (50100, 10), (58000, 2.5)
for scale in [(1, 1), (1 / 10000, 1 / 4)]:
    s = lambda p: (p[0] * scale[0], p[1] * scale[1])
    print('closest to A:', 'B' if distance(s(A), s(B)) < distance(s(A), s(C)) else 'C')
# prints: closest to A: B
# prints: closest to A: C
